def fires(b):
    # the cell directly on top of the opponent's last stone completes four for the opponent
    c = b.last_col
    if c is None:
        return False
    r = b.last_row + 1
    return (r, c) in b.their_wins

def level(b):
    if not fires(b):
        return 0
    n = len(b.their_playable_wins)
    return 9 if n >= 2 else 7

def line_len(b, r, c, dr, dc, p):
    n = 1
    for s in (1, -1):
        rr = r + s * dr
        cc = c + s * dc
        while 0 <= rr < 6 and 0 <= cc < 7 and b.grid[rr][cc] == p:
            n += 1
            rr += s * dr
            cc += s * dc
    return n

def nonvert_blocks(b):
    k = 0
    for (r, c) in b.their_playable_wins:
        for d in ((0, 1), (1, 1), (1, -1)):
            if line_len(b, r, c, d[0], d[1], 2) >= 4:
                k += 1
                break
    return k

def fires(b):
    # opponent threatens to win right now on a horizontal or diagonal line
    return nonvert_blocks(b) >= 1

def level(b):
    k = nonvert_blocks(b)
    if k >= 2:
        return 9
    if k == 1:
        return 7
    if b.their_playable_wins:
        return 3
    return 0

def stacked(b):
    # opponent has two win cells directly on top of each other in a column
    for (r, c) in b.their_wins:
        if (r + 1, c) in b.their_wins:
            return True
    return False

def score_lost(b):
    pw = b.their_playable_wins
    if len(pw) >= 2:
        return 3
    for (r, c) in pw:
        if (r + 1, c) in b.their_wins:
            return 3
    if pw and stacked(b):
        return 2
    if stacked(b):
        return 2
    if pw:
        return 1
    return 0

def fires(b):
    # the opponent has an unstoppable threat: two immediate wins, or a must-block with another win right above it,
    # or two opponent win cells stacked in one column
    return score_lost(b) >= 2

def level(b):
    return [0, 3, 7, 9][score_lost(b)]

def dead_runs(b):
    # horizontal runs of 2+ opponent stones whose both ends are my stone or the board edge
    k = 0
    for r in range(6):
        c = 0
        while c < 7:
            if b.grid[r][c] == 2:
                s = c
                while c < 7 and b.grid[r][c] == 2:
                    c += 1
                e = c
                if e - s >= 2:
                    left = s == 0 or b.grid[r][s - 1] == 1
                    right = e == 7 or b.grid[r][e] == 1
                    if left and right:
                        k += 1
            else:
                c += 1
    return k

def above_last(b):
    c = b.last_col
    if c is None:
        return False
    return (b.last_row + 1, c) in b.their_wins

def fires(b):
    return dead_runs(b) >= 2 or (dead_runs(b) >= 1 and above_last(b))

def level(b):
    k = dead_runs(b) + (2 if above_last(b) else 0)
    return min(9, 2 * k)
